// The shared W1 <-> database contract corpus. Every entry is run through the REAL W1 validator (dist/wall/validate.js) by tests/game-id-wall-w2.test.js and
// through the database's private.wall_document_errors() by tests/integration/wall-w2-db.sql (generated from this file by
// scripts/generate-wall-w2-db-contract.mjs). The two must return the same error set for every entry - that is what keeps the narrow SQL port from drifting
// away from W1. Add a case here whenever W1 validation gains behavior; the drift guard then forces the database side to be taught the same thing.
import { createDocument } from "../dist/wall/schema.js";
import { createTextPayload } from "../dist/wall-kit/text.js";
import "../dist/wall-kit/register.js";   // registers every element type, background kind and embed provider with the W1 validator

const rect = (id, over = {}) => ({ id, type: "rect", x: 10, y: 10, width: 100, height: 100, z: 0, payload: { fill: "#aabbcc" }, ...over });
const docWith = (...elements) => { const d = createDocument(); d.stages[0].elements = elements; return d; };
const rectWithPayload = payload => docWith(rect("r1", { payload: { fill: "#aabbcc", ...payload } }));
const textEl = (id, over = {}, extra = {}) => rect(id, { type: "text", width: 600, height: 150, payload: createTextPayload(over), ...extra });
const docWithText = (over, extra) => docWith(textEl("t1", over, extra));
const UUID = "3f2b8c1e-5a4d-4e7b-9c60-1d2e3f4a5b6c";
const imageEl = (id, over = {}, extra = {}) => rect(id, { type: "image", payload: { assetId: UUID, fit: "cover", posX: 50, posY: 50, opacity: 1, ...over }, ...extra });
const gamidEl = (id, over = {}, extra = {}) => rect(id, { type: "gamid", width: 600, height: 300, payload: { block: "profile", ...over }, ...extra });
const dataEl = (id, payload, extra = {}) => rect(id, { type: "gamidData", width: 600, height: 200, payload, ...extra });
const dataText = (over = {}) => { const { text: _text, ...style } = createTextPayload(over); return style; };
const embedEl = (id, providerKey, data, extra = {}) => rect(id, { type: "embed", width: 600, height: 340, payload: { providerKey, data }, ...extra });
const withBackground = (background, stageBackground) => { const d = docWith(rect("r1")); if (background !== undefined) d.background = background; if (stageBackground !== undefined) d.stages[0].background = stageBackground; return d; };const withStages = stages => ({ ...createDocument(), stages });

